function v37ExtractAdaptedDistance(text){let total=0;for(const line of String(text||"").split(/\n/)){const m=line.match(/\b(\d{1,3})\s*[x×]\s*(\d{2,4})\b/i);if(m)total+=Number(m[1])*Number(m[2])}return total}
