    const rest=clause.match(/(?:all\s+(?:based|with)|based)\s+(?:off|on)?\s*(?:a\s+)?(\d+|ten|twenty|thirty|forty|sixty)\s*(?:seconds?|secs?|s)\s*(?:rest)?/i);
