  const withPoints=rows.filter(row=>v3Points(row)>0).sort((a,b)=>v3Points(b)-v3Points(a)||Number(a.result_seconds||99999)-Number(b.result_seconds||99999));
  if(withPoints[0])return v3Stroke(withPoints[0].stroke);
