  return {status:"ok",source:sourceLabel,targetSeconds:seconds,cycleSeconds:cycle,primary:`${v3129Clock(seconds)} on ${v3129Clock(cycle)}`,secondary:`${sourceLabel} ${v3129Clock(anchor.result_seconds)}`};
